import{_ as a,a as i}from"./chunks/daily-2026-08-18-fcop-atomic-commit.C8vGawHG.js";import{_ as s,C as n,o,c as r,E as l,a2 as c}from"./chunks/framework.Cm6XCzck.js";const v=JSON.parse('{"title":"Files, Paths, and Events: Implementing and Testing the FCoP State Machine","description":"","frontmatter":{"title":"Files, Paths, and Events: Implementing and Testing the FCoP State Machine","date":"2026-08-18","column":"open-source-engineering","category":"daily","article_type":"project-research","edition":"research-center","research_question":"How can FCoP artifact identity, path-addressed state, event history, and atomic publication become an implementable, testable coordination kernel without overstating its guarantees?","summary":"Grounded in the current specification, code, and targeted tests, this article explains five lifecycle locations, seven legal transitions, transition events, and the write-fsync-replace-cleanup algorithm while preserving concurrency, durability, and exactly-once boundaries.","item_id":"MANUAL-20260818-FCOP","lifecycle":"Published","cover":"/assets/covers/daily-2026-08-18-fcop-file-state-machine-cover.webp","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true,"sources":["research/manual-runs/2026-08-18-guided-article-pipeline-round1/02-source-register.md","research/manual-runs/2026-08-18-guided-article-pipeline-round1/02-fact-matrices.md","research/manual-runs/2026-08-18-guided-article-pipeline-round1/02-article-briefs.md","research/manual-runs/2026-08-18-guided-article-pipeline-round1/02-independent-editorial-review.md"]},"headers":[],"relativePath":"en/engineering/2026-08-18-fcop-file-state-machine.md","filePath":"en/engineering/2026-08-18-fcop-file-state-machine.md","lastUpdated":1787044313000}'),p={name:"en/engineering/2026-08-18-fcop-file-state-machine.md"};function d(h,e,u,m,k,g){const t=n("ArticleCover");return o(),r("div",null,[l(t,{image:"/assets/covers/daily-2026-08-18-fcop-file-state-machine-cover.webp",kicker:"Open-source Engineering · Project Research",title:"Files, Paths, and Events: Implementing and Testing the FCoP State Machine",summary:"Using the current specification, code, and targeted tests, this article examines five lifecycle locations, seven legal transitions, transition events, and the write–fsync–replace–cleanup algorithm—without overstating concurrency, durability, or exactly-once guarantees.",version:"MANUAL-20260818-FCOP",status:"Independent Editorial PASS · 2026-08-18",languageHref:"/zh/engineering/2026-08-18-fcop-file-state-machine",languageLabel:"中文"}),e[0]||(e[0]=c(`<h1 id="files-paths-and-events-implementing-and-testing-the-fcop-state-machine" tabindex="-1">Files, Paths, and Events: Implementing and Testing the FCoP State Machine <a class="header-anchor" href="#files-paths-and-events-implementing-and-testing-the-fcop-state-machine" aria-label="Permalink to &quot;Files, Paths, and Events: Implementing and Testing the FCoP State Machine&quot;">​</a></h1><blockquote><p>FCoP is not just a directory watcher. A working implementation must preserve four contracts at once: artifact identity, path-addressed state, transition evidence, and atomic publication.</p></blockquote><p><strong>Series map:</strong> read <a href="/joinwell52/en/engineering/2026-08-18-files-first-multi-agent-governance">the governance argument</a> first if you are still deciding why files are a useful starting point. After this protocol implementation, continue with <a href="/joinwell52/en/digital-employee/2026-08-18-cursor-ai-development-team">the Cursor operating guide</a>.</p><p>Suppose an agent changes <code>status</code> to <code>done</code> inside a task while the file remains in <code>active/</code>. A dashboard trusts the field, a scheduler trusts the directory, and a reviewer sees only a success log. The system now has three answers and no authoritative current fact.</p><p>The common mistake in file-based coordination is to treat “written to disk” as “protocol complete.” What must actually be implemented is a state machine: which artifacts may enter, which location is authoritative, who may perform each transition, what evidence a transition leaves, and what a crash can expose.</p><p>The <a href="https://github.com/joinwell52-AI/FCoP/blob/a859e6747fe6e5e2d686e0114c77774726d7f748/spec/fcop-v3-spec.md" target="_blank" rel="noreferrer">FCoP v3 specification</a> states the model compactly: files carry the protocol, location defines state, and events record history. The following is the smallest useful implementation of that idea.</p><h2 id="contract-1-artifact-identity" tabindex="-1">Contract 1: artifact identity <a class="header-anchor" href="#contract-1-artifact-identity" aria-label="Permalink to &quot;Contract 1: artifact identity&quot;">​</a></h2><p>FCoP defines four IPC envelopes: <code>TASK</code>, <code>REPORT</code>, <code>ISSUE</code>, and <code>REVIEW</code>. Their identity semantics differ: <code>TASK</code> and <code>REPORT</code> use sender-to-recipient routing, <code>ISSUE</code> identifies its reporter, and <code>REVIEW</code> binds to the subject under review. For example:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>TASK-20260818-001-PM-to-DEV.md</span></span>
<span class="line"><span>REPORT-20260818-002-DEV-to-PM.md</span></span>
<span class="line"><span>ISSUE-20260818-003-QA.md</span></span></code></pre></div><p>A review is attached to its subject rather than masquerading as another routed message:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>REVIEW-20260818-004-QA-on-report-002.md</span></span></code></pre></div><p>The body should repeat fields that a schema can validate:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">---</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">protocol</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">fcop</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">version</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">TASK</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">sender</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">PM</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">recipient</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">DEV</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">priority</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">P1</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">subject</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Implement CSV export and tests</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">task_id</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">TASK-20260818-001-PM-to-DEV</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">date</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2026-08-18T15:00:00+08:00</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">---</span></span></code></pre></div><p>At minimum, validate the filename prefix against <code>type</code>, match <code>task_id</code> to the filename stem when that optional field is present, require legal sender and recipient values, parse timestamps, and reject obvious cycles in <code>ref_task</code>/<code>parent</code> relationships. Filename structure improves routing and early error detection; it is not a replacement for authorization or a complete business schema.</p><h2 id="contract-2-path-addressed-lifecycle-state" tabindex="-1">Contract 2: path-addressed lifecycle state <a class="header-anchor" href="#contract-2-path-addressed-lifecycle-state" aria-label="Permalink to &quot;Contract 2: path-addressed lifecycle state&quot;">​</a></h2><p>The current FCoP lifecycle has five locations:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>_lifecycle/inbox</span></span>
<span class="line"><span>_lifecycle/active</span></span>
<span class="line"><span>_lifecycle/review</span></span>
<span class="line"><span>_lifecycle/done</span></span>
<span class="line"><span>_lifecycle/archive</span></span></code></pre></div><p><img src="`+a+`" alt="FCoP&#39;s five lifecycle locations, seven legal transitions, and separate REPORT and governance REVIEW artifacts"></p><p><em>Figure 1. The path defines the TASK&#39;s current state. A REPORT is execution evidence and a governance REVIEW is a separate judgment; neither moves the TASK by itself. Source: Research Center synthesis of the FCoP v3 specification and implementation.</em></p><p>The dashed lines are not automatic transitions. A REPORT is execution evidence and a governance REVIEW is a separate judgment; neither can move a TASK to <code>done/</code> by itself.</p><p>A minimal transition table is:</p><table tabindex="0"><thead><tr><th>Operation</th><th>From</th><th>To</th><th>Principal responsibility</th></tr></thead><tbody><tr><td>create/write</td><td>external</td><td>inbox</td><td>creator</td></tr><tr><td>claim</td><td>inbox</td><td>active</td><td>worker or lifecycle governor</td></tr><tr><td>submit</td><td>active</td><td>review</td><td>worker</td></tr><tr><td>finish</td><td>active</td><td>done</td><td>authorized terminal actor</td></tr><tr><td>approve</td><td>review</td><td>done</td><td>reviewer or leader</td></tr><tr><td>reject</td><td>review</td><td>active</td><td>reviewer or leader</td></tr><tr><td>archive</td><td>done</td><td>archive</td><td>ADMIN or leader</td></tr></tbody></table><p>Location should be the authoritative lifecycle fact. A body-level status can be derived or retained for compatibility, but it must not establish a second competing state machine.</p><blockquote><p><strong>A <code>status: done</code> field is not lifecycle state. Path is the authoritative present; compressing location and transition history into one field destroys the review trail.</strong></p></blockquote><p>The <a href="https://github.com/joinwell52-AI/FCoP/blob/a859e6747fe6e5e2d686e0114c77774726d7f748/docs/releases/3.2.5.md" target="_blank" rel="noreferrer">3.2.5 release note</a> also sharpens role boundaries: a worker reports and stops; ADMIN or a leader performs archival. “I finished my work” and “the system has accepted and closed the work” are different claims.</p><h2 id="contract-3-event-evidence" tabindex="-1">Contract 3: event evidence <a class="header-anchor" href="#contract-3-event-evidence" aria-label="Permalink to &quot;Contract 3: event evidence&quot;">​</a></h2><p>Moving an old file updates a path but does not explain history. FCoP v3 therefore keeps events in the TASK front matter as an append-only <code>transitions:</code> array:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">transitions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">at</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2026-08-18T15:18:43+08:00</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    from</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">active</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    to</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">review</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    by</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">DEV-01</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    tool</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">submit_task</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    note</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">REPORT-20260818-002-DEV-to-PM</span></span></code></pre></div><p>The five required fields are <code>at</code>, <code>from</code>, <code>to</code>, <code>by</code>, and <code>tool</code>; <code>note</code> and <code>supersedes</code> are optional. Because the transition travels inside the TASK, it does not need a separate event ID to identify its subject. An auditor can compare the current path with the latest transition and flag an artifact in <code>review/</code> whose trace still ends in <code>active</code>.</p><p>Current state and history should cross-check one another, not duplicate the same mutable field.</p><h2 id="contract-4-atomic-publication" tabindex="-1">Contract 4: atomic publication <a class="header-anchor" href="#contract-4-atomic-publication" aria-label="Permalink to &quot;Contract 4: atomic publication&quot;">​</a></h2><p>For a new TASK, do not write directly to the final path. Append the creation transition in memory, write the complete text to a temporary file in the destination directory, fsync it, and replace the final inbox path.</p><p>A state transition must not rename first and append an event later. The current implementation reads the source TASK, appends the transition in memory, writes the complete new TASK into a temporary file inside the destination directory, fsyncs it, replaces the destination path, and only then removes the source.</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">def</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> transition</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(source, target_stage, event):</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    require_legal_edge(source, target_stage, event.tool)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    require_same_mount(source, target_stage)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    old_text </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> read(source)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    new_text </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> append_to_transitions(old_text, event)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    tmp </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> unique_temp_in(target_stage)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    write_all(tmp, new_text)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    fsync_file(tmp)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    os.replace(tmp, destination_in(target_stage, source.name))</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    unlink_source_after_commit(source)</span></span></code></pre></div><p><img src="`+i+`" alt="FCoP&#39;s commit sequence from reading the source through temp write, fsync, replace, and source cleanup"></p><p><em>Figure 2. <code>os.replace</code> is the destination publication point. Source cleanup follows, so the complete cross-directory operation is not one syscall. Source: Research Center synthesis of FCoP&#39;s <code>transition.py</code> implementation.</em></p><p><a href="https://pubs.opengroup.org/onlinepubs/9799919799/functions/rename.html" target="_blank" rel="noreferrer">POSIX.1-2024 <code>rename</code></a> specifies an atomic rename action under its defined conditions and exposes <code>EXDEV</code> for cross-filesystem cases. The <a href="https://pubs.opengroup.org/onlinepubs/9799919799/xrat/V4_xbd_chap01.html" target="_blank" rel="noreferrer">POSIX rationale</a> is equally important: directory operations may be atomic and serializable without being durable on storage.</p><p>The replace commit point prevents an observer from reading a partial new TASK at the destination and puts the destination path and new transition in the same file. It does not imply that:</p><ul><li>exactly one worker automatically wins a claim;</li><li>data is durable after every crash;</li><li>a network filesystem behaves like a local disk;</li><li>the workflow is deadlock-free; or</li><li>a task executes exactly once.</li></ul><p>Claim contention needs an explicit winner model or single-writer governor. Repeated effects require idempotency keys. Recovery requires reconciling paths and events. None of these properties follows from the word “atomic.”</p><h2 id="lifecycle-review-and-governance-review-are-orthogonal" tabindex="-1">Lifecycle review and governance REVIEW are orthogonal <a class="header-anchor" href="#lifecycle-review-and-governance-review-are-orthogonal" aria-label="Permalink to &quot;Lifecycle review and governance REVIEW are orthogonal&quot;">​</a></h2><p>FCoP uses “review” in two deliberately separate ways:</p><ul><li><code>_lifecycle/review/</code> means that a task is awaiting review;</li><li><code>reviews/REVIEW-*</code> is an artifact containing a reviewer’s judgment.</li></ul><p>A task can enter the review location before a valid REVIEW exists. A REVIEW artifact may reject rather than approve. FCoP conformance does not automatically bind the two chains. A host may add stricter checks for subject identity, reviewer authority, and references from high-risk approval actions, but that is a governance extension rather than a default protocol requirement.</p><p>The extra artifact preserves accountability: lifecycle code owns location, while a reviewer owns the judgment.</p><h2 id="test-invariants-not-just-successful-moves" tabindex="-1">Test invariants, not just successful moves <a class="header-anchor" href="#test-invariants-not-just-successful-moves" aria-label="Permalink to &quot;Test invariants, not just successful moves&quot;">​</a></h2><p>For this article, two FCoP lifecycle test files were rerun:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>python -m pytest \\</span></span>
<span class="line"><span>  tests/test_lifecycle/test_atomic.py \\</span></span>
<span class="line"><span>  tests/test_lifecycle/test_project_v3_writes.py -q</span></span></code></pre></div><p>The result was <code>22 passed in 0.89s</code>. This is a local result for two files at the cited commit, not a full-suite result, performance benchmark, or proof of distributed behavior. Actual coverage and proposed follow-up tests must remain separate.</p><p><strong>Covered by the 22 tests:</strong> creation in <code>inbox</code>, a creation transition, rejection of path separators and invalid event arguments, <code>inbox → active</code>, transition evidence in the destination, temporary-file cleanup, rejection of skipped stages and wrong tools, a full happy path, missing-source handling, project-level lifecycle flow, idempotent archival, cross-bucket lookup, and v2 compatibility.</p><p><strong>Recommended identity and governance additions:</strong> complete filename/front-matter schema validation, REVIEW subject and decision checks, governance permissions, and explicit worker archive denial.</p><p><strong>Recommended fault and concurrency additions:</strong> crash during temporary writing, destination commit followed by source-cleanup failure, concurrent claimants, duplicate reports and idempotency, permission errors, full disks, missing directories, and <code>EXDEV</code>.</p><p>Happy-path tests show that code runs. Fault tests show what the protocol protects.</p><h2 id="the-state-machine-is-only-the-coordination-kernel" tabindex="-1">The state machine is only the coordination kernel <a class="header-anchor" href="#the-state-machine-is-only-the-coordination-kernel" aria-label="Permalink to &quot;The state machine is only the coordination kernel&quot;">​</a></h2><p>A usable system usually adds a schema validator, lifecycle governor, recovery scanner, permission adapter, searchable view, and runtime adapter. The runtime adapter—not FCoP—calls models and tools, owns sandboxes, and executes tests.</p><p><a href="https://github.com/joinwell52-AI/FCoP/blob/a859e6747fe6e5e2d686e0114c77774726d7f748/adr/ADR-0038-fcop-boundary-charter.md" target="_blank" rel="noreferrer">ADR-0038</a> makes that boundary explicit: FCoP describes, externalizes, and coordinates work; it does not execute or globally orchestrate it. Keeping that boundary narrow prevents a file protocol from becoming another inseparable platform.</p><h2 id="four-contracts-make-the-state-inspectable" tabindex="-1">Four contracts make the state inspectable <a class="header-anchor" href="#four-contracts-make-the-state-inspectable" aria-label="Permalink to &quot;Four contracts make the state inspectable&quot;">​</a></h2><p>A file state machine is useful only if it can always answer: what artifact is this, where is it now, how did it get here, and could an observer have seen a partial version?</p><p>Artifact identity, path state, event evidence, and atomic publication answer those questions. Authorization, idempotency, and recovery complete the minimum coordination kernel.</p><p>The evidence in this article does not establish network-filesystem behavior, high-contention claims, cross-machine consistency, or exactly-once execution. Those are not gaps to fill with architecture slogans. They are failure models to turn into tests.</p><p>With testable transitions and a defined commit point in place, the next problem is operational: connecting the protocol to everyday development without turning multiple agents into unrelated chat windows. Continue with <a href="/joinwell52/en/digital-employee/2026-08-18-cursor-ai-development-team">Running an AI Development Team in Cursor: From Requirement to Testable Delivery</a>.</p><h2 id="sources" tabindex="-1">Sources <a class="header-anchor" href="#sources" aria-label="Permalink to &quot;Sources&quot;">​</a></h2><ul><li><a href="https://github.com/joinwell52-AI/FCoP/blob/a859e6747fe6e5e2d686e0114c77774726d7f748/spec/fcop-v3-spec.md" target="_blank" rel="noreferrer">FCoP v3 specification</a></li><li><a href="https://github.com/joinwell52-AI/FCoP/blob/a859e6747fe6e5e2d686e0114c77774726d7f748/docs/releases/3.2.5.md" target="_blank" rel="noreferrer">FCoP 3.2.5 release notes</a></li><li><a href="https://github.com/joinwell52-AI/FCoP/tree/a859e6747fe6e5e2d686e0114c77774726d7f748/tests/test_lifecycle" target="_blank" rel="noreferrer">FCoP lifecycle tests</a></li><li><a href="https://pubs.opengroup.org/onlinepubs/9799919799/functions/rename.html" target="_blank" rel="noreferrer">POSIX.1-2024 rename</a></li><li><a href="https://pubs.opengroup.org/onlinepubs/9799919799/xrat/V4_xbd_chap01.html" target="_blank" rel="noreferrer">POSIX Base Definitions rationale</a></li><li><a href="https://github.com/joinwell52-AI/FCoP/blob/a859e6747fe6e5e2d686e0114c77774726d7f748/adr/ADR-0038-fcop-boundary-charter.md" target="_blank" rel="noreferrer">ADR-0038: FCoP Boundary Charter</a></li></ul>`,63))])}const E=s(p,[["render",d]]);export{v as __pageData,E as default};
